import json,re
d=json.load(open('layout.json'))
# print structured sections with headings
def walk(o,out,depth=0):
    if isinstance(o,dict):
        t=o.get('type')
        if t=='heading':
            out.append(('H'+str(o.get('level','?')), o.get('text','')))
        if t=='paragraph':
            txt=''.join(x.get('text','') if isinstance(x,dict) else '' for x in o.get('inlineContent',[]))
            out.append(('P',txt))
        for k,v in o.items():
            if k!='inlineContent': walk(v,out,depth+1)
    elif isinstance(o,list):
        for v in o: walk(v,out,depth+1)
out=[]; walk(d,out)
seen=set(); res=[]
for typ,txt in out:
    key=(typ,txt)
    if key in seen: continue
    seen.add(key); res.append((typ,txt))
for typ,txt in res:
    if typ.startswith('H'): print()
    print(typ, '|', txt[:300])
